INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-01','CN0102','W13S04','分股源强与残液','表3.3.7-13、3.3.7.4','低浓组15894m³/a，高浓组1114m³/a；分股源强表已结构化。高浓蒸馏/精馏残液235.68t/a设计危废，实验室废液1t/a、废催化剂0.2t/a另列；循环冷却水泵3台合计500m³/h是循环能力非废水站能力。制水浓缩水不代表废水膜。截图重定向，采用正文。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-02','CN0195','W01S07','分股源强与排放口径冲突','表3.4-4/5、5.1.2','分股总计33059t/a，其中综合组20057、循环水13002；5.1.2另称100.2t/d项目、117.3t/d全厂，与300天工作制不闭合；表3.4-4循环水氨氮5mg/L，表3.4-5为10mg/L。保留原报告，不判实际；正文现有预处理与拟建500t/d站用词不一致。表3.2-5两条分子筛线膜分离设备为物料工艺，膜型不明，纯水RO亦非污水膜；两种分子筛中间产品各1100吨不能加到3000吨催化剂。表3.4-6污泥12t/a设计。截图超时。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-03','CN0296','S042-01','迁建历史排放及预测','迁建污染物排放汇总表，p179前','北厂原864m³/a，削减684，迁建后预计180；南厂1140，合计1320，原批1843.2，净减523.2。北厂历史TN系本次补核；表明确仍有180m³/a预测保留排水，与拟拆除叙述并存，需核实际厂界/生活设施；不是UF站进水。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-04','CN0297','S042-01','南厂排放负荷','迁建污染物排放汇总表','设计生活排水1140m³/a接管与外排量同值，5项接管及环境外排负荷已录；非工业回用处理量。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-05','CN0240','W08S09','2018验收分质深挖','pp25–28 图4.1-5/6','WW1间歇沉淀→中间水池1→铁盐、pH、两级絮凝→斜板沉淀→中间水池2→pH调节/中间水池3→砂滤及活性炭→中间水池4→RO；反洗水回池2；酸洗液WW2沉淀、双氧水氧化，与离心废水/RO浓水合并三效蒸发；蒸馏水生产回用、废盐危废外运、污泥压滤外运。图4.1-5文本提及免烧砖用部分水，具体连接截图超时未强画。','WEB_COMPANY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-06','CN0240','S043-01','2019验收报告水量与蒸汽冲突','表3.4-1/2、图3.4-1/2/3','表3.4-1实际22918+4416=27334，与表总计17334冲突（图3.4-2列27334），保留原值。新水设计86078、实际92419；纯水新水74550/81851、生活6480/5520、绿化5048/5048m³/a；实际列为报告年口径，非单日监测。纯水UF/RO设计15m³/h非污水膜；3.4.2纯水废水同时出现雨水/污水管网两种描述。蒸汽平衡81095t/a，总述51840m³/a单位和口径不同；三效24040t/a、80.13t/d、回锅炉冷凝22838t/a、损耗1202t/a，未获单元实际账单。500m³事故池非处理能力。截图超时。','WEB_COMPANY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-07','CN0132','S043-02','节水披露','2025-10-16问询回复第11页','公司称负载型贵金属催化剂生产节水75%以上、循环利用废水；未披露基准、定量进出水、膜设备和厂区边界，不能作为全厂实际回用率或成本。','WEB_COMPANY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-08','CN0242','S043-03','新增依托项目','2026-08-28公示检索摘录','金属有机新材料及中间体项目利用现有1#车间改造，无新增建筑，依托原动力车间、污水处理和消防水池等；未得到报告正文，不能推断新增流量或运行状态。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-09','CN0190','S043-06','上游废水资源化','2024院校企业介绍','恒力炼化配套项目规划3000吨氢溴酸（钠）装置，从恒力污水处理前的废水提取溴元素，用于加工钴锰溴催化剂。为原料资源化，不是众智自身废水处理；周期及实际投运未核。','WEB_SECONDARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-10','CN0299','turn787991search0','许可厂址及分项','2026-11-06名单第10行','2026-08-07至2031-08-06，1万吨/年含HW46 600、HW50 9400；许可不是实产；2026-07-31拟许可同一地址。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-11','CN0300','turn787991search0','许可与依托站条件','2026-11-06名单第19行','2026-11-06至2031-11-05，HW50 5040t/a及废碱液1万吨/年；依托站停止运行需终止经营，条件只属于本公司不串给众智。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-12','CN0301','S043-04','拟许可分项','2026-07-31附件第4家','HW46/50废催化剂4.14万吨/年，另废油1.2万吨/年、HW11蒸馏0.6万吨/年、废碱2万吨/年、废包装清洗0.23万吨/年为其他业务，不计本厂产生水量；未得核发后名单对应行。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-13','CN0302','S043-05','贵金属废剂拟许可','2026-10-30附件第2家','含铂400、含银500t/a共900，拟许可有效5年；非生产产能或实际处理量。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N043-14','CN0072','turn787991search0','许可状态补证','2026-11-06名单第64行','HW50 1.3万吨/年，2024-01-05至2027-02-22，与原设计1.3万吨口径不同，不相加；未确认NF实际投运。','WEB_PRIMARY','公开正文/索引，未归档原件','2026-11-28');
