INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA043-01','R043-01','CN0102','expansion_distillation','screening',2,'分质减量、回用和能耗优化','高浓组COD21817.8、溶解性固体9699.3mg/L设计，不宜直接RO。低浓组单独回用需求与水质核证后比较UF/RO，既有蒸馏保留，避免浓水再增加危废；成本用实际产水与蒸汽药剂耗比选。','conditional','浓水合法去向、实际进水及水质、回用需求须核','INFERRED；W13S04；2800吨设计，制纯水RO非污水膜；高低浓分开','工程候选非已建；原报告阶段不得升级','实际投运/产水盐氮磷与共享站工艺','分股采样、预处理及膜小试、盐/金属衡算、蒸汽/药耗和生命周期费用比选','源头减排、既有物化生化或蒸馏维持',NULL,NULL,NULL,NULL,NULL,NULL,'六维数据不足，难度未知','2026-11-28');
