INSERT INTO membrane_retrofits (assessment_id,review_id,site_id,scope_key,option_key,revision,objective,proposed_route,feasibility,hard_constraints,evidence_basis,assumptions,missing_inputs,validation_plan,alternatives,feed_risk,pretreatment_risk,concentrate_risk,integration_risk,operational_risk,compliance_economics_risk,score_basis,updated_on) VALUES ('RA043-02','R043-02','CN0195','production-2015','screening',2,'分质减量、回用和能耗优化','优先核2021分离酸碱水后回用实际流程；仅在分质后盐度、胺类、结垢及回用目标确认时筛选UF/RO或酸碱回收，保持生化与源头回收比较。','conditional','浓水合法去向、实际进水及水质、回用需求须核','INFERRED；W01S07；2015设计表3.4-5，现有/拟建叙述及日年流量不一致；物料膜和纯水RO非污水膜','工程候选非已建；原报告阶段不得升级','2021整改后真实分股、膜和回用；表冲突待核','分股采样、预处理及膜小试、盐/金属衡算、蒸汽/药耗和生命周期费用比选','源头减排、既有物化生化或蒸馏维持',NULL,NULL,NULL,NULL,NULL,NULL,'六维数据不足，难度未知','2026-11-28');
